import{NextResponse}from'next/server';import{adminEmail,cookieName,sessionToken,validCredentials}from'../../../../lib/adminAuth';
const attempts=new Map<string,{count:number;until:number}>();
export async function POST(request:Request){const ip=request.headers.get('x-forwarded-for')?.split(',')[0]||'local';const current=attempts.get(ip);if(current&&current.until>Date.now())return NextResponse.json({ok:false,message:'Too many attempts. Try again shortly.'},{status:429});let body:{email?:string;password?:string};try{body=await request.json()}catch{return NextResponse.json({ok:false,message:'Invalid request.'},{status:400})}if(!validCredentials(body.email||'',body.password||'')){const count=(current?.count||0)+1;attempts.set(ip,{count,until:count>=5?Date.now()+5*60_000:0});return NextResponse.json({ok:false,message:'The administrator credentials are incorrect.'},{status:401})}attempts.delete(ip);const host=request.headers.get('host')||'';const previewMode=host.includes('localhost')||host.includes('127.0.0.1')||host.endsWith('.e2b.app')||host.endsWith('.arena.site');const response=NextResponse.json({ok:true,email:adminEmail,developmentToken:previewMode?sessionToken():undefined});const https=request.headers.get('x-forwarded-proto')==='https'||request.url.startsWith('https://');response.cookies.set(cookieName,sessionToken(),{httpOnly:true,sameSite:https?'none':'lax',secure:https,partitioned:https&&process.env.NODE_ENV!=='production',path:'/',maxAge:60*60*8});return response}
